267	  function mintToken(now, seq = tokenSequence) {
268	    // Pure candidate: nothing is committed until the event is on disk, so a
269	    // failed append rolls all the way back. Pids and instance ids can coincide
270	    // after a restart, so skip any sequence that collides with a credential
271	    // reconstructed from the log. The caller threads the sequence through when
272	    // it mints several tokens for one atomic write.
273	    let token;
274	    do {
275	      seq += 1;
276	      token = `lease-${process.pid}-${registryId}-${seq}-${now.toString(36)}`;
277	    } while (knownTokens.has(token));
278	    return { token, seq };
279	  }
280	
281	  function newExpiryNode(token, expiresAt, heapSeq) {
282	    return { token, expiresAt, heapSeq, order: queueOrder++ };
283	  }
284	
285	  // One node in every heap a lease occupies. The nodes are independent: each
286	  // heap retires its own stale entries lazily. Every push also bumps the
287	  // owner's heap version, so a reconcile at an unchanged reading still
288	  // re-judges after a grant or renewal changed the heap contents.
289	  // Push one lease node to the global expiry heap and to every owner
290	  // whose heap drives lazy observation. A share already recorded as
291	  // retired at an owner (a replay structurally superseding an unswept
292	  // lease) only needs its global node - it must be reclaimable - and is
293	  // skipped on that owner's heap, since its occupation was never
294	  // reconstructed there. Every other push bumps the owner's heap
295	  // version, so a reconcile at an unchanged reading still re-judges
296	  // after a grant or renewal changed the heap contents.
297	  function pushLeaseHeaps(token, lease) {
298	    const node = newExpiryNode(token, lease.expiresAt, lease.heapSeq);
299	    expiryQueue.push(node);
300	    const rs = resourceStates.get(lease.resource);
301	    rs.heap.push(newExpiryNode(token, lease.expiresAt, lease.heapSeq));
302	    rs.version += 1;
303	    for (const quota of lease.chain) {
304	      quota.heap.push(newExpiryNode(token, lease.expiresAt, lease.heapSeq));
305	      quota.version += 1;
306	    }
307	  }
308	
309	  // Peek an owner heap for a lease that is live at `now` without
310	  // mutating anything: stale nodes are inspected but left in place for a
311	  // later reconcile to retire or for a dropStaleSlots displacement.
312	  function hasLiveHeapNode(owner, now) {
313	    for (const node of owner.heap.nodes) {
314	      const lease = leases.get(node.token);
315	      if (lease !== undefined && lease.heapSeq === node.heapSeq && node.expiresAt > now) {
316	        return true;
317	      }
318	    }
319	    return false;
320	  }
321	
322	  // Remove every node naming `token` from one expiry heap. Used when a
323	  // replay structurally supersedes an expired, unswept lease: the stale
324	  // share never occupied the reconstructed owner table, so its node leaves
325	  // the owner heap without any live-usage movement. Tokens are globally
326	  // unique, so matching the token alone (not the heap sequence) separates a
327	  // superseded lease from a fresh credential that happens to share seq 0.
328	  function removeHeapNodes(heap, token) {
329	    let i = 0;
330	    while (i < heap.nodes.length) {
331	      if (heap.nodes[i].token === token) {
332	        heap.nodes.splice(i, 1);
333	      } else {
334	        i += 1;
335	      }
336	    }
337	    // Restore the heap invariant in linear time after the removals.
338	    const nodes = heap.nodes;
339	    for (let j = (nodes.length >>> 1) - 1; j >= 0; j -= 1) {
340	      let parent = j;
341	      for (;;) {
342	        const left = parent * 2 + 1;
343	        const right = left + 1;
344	        let smallest = parent;
345	        if (left < nodes.length && expiresBefore(nodes[left], nodes[smallest])) {
346	          smallest = left;
347	        }
348	        if (right < nodes.length && expiresBefore(nodes[right], nodes[smallest])) {
349	          smallest = right;
350	        }
351	        if (smallest === parent) {
352	          break;
353	        }
354	        [nodes[parent], nodes[smallest]] = [nodes[smallest], nodes[parent]];
355	        parent = smallest;
356	      }
357	    }
358	  }
359	
360	  function isLive(lease, now) {
361	    return lease !== undefined && lease.expiresAt > now;
362	  }
363	
364	  function resourceStateFor(resource) {
365	    let rs = resourceStates.get(resource);
366	    if (rs === undefined) {
367	      rs = {
368	        capacity: 1,
369	        chain: [],
370	        declared: false,
371	        live: 0,
372	        heap: new ExpiryQueue(),
373	        // Shares observed expired (and so not counted at the current
374	        // reading) but still in the lease table awaiting a sweep. The map is
375	        // reversible: a reading that goes backwards revives entries that are
376	        // live again, exactly as a fresh isLive judgment would.
377	        retired: new Map(),
378	        watermark: -Infinity,
379	        checkedVersion: -1,
380	        // Heap layout version, bumped whenever a node is pushed (a grant or
381	        // a renewal moves a share's expiry): a reconcile at an unchanged
382	        // reading must still run again after a renewal so the new expiry is
383	        // judged at that reading.
384	        version: 0,
385	        // quota -> number of queued positions on this resource under it; the
386	        // set drives quota-indexed wake seeding.
387	        waitRefs: new Map(),
388	      };
389	      resourceStates.set(resource, rs);
390	    }
391	    return rs;
392	  }
393	
394	  function quotaChainFor(leafId) {
395	    const chain = [];
396	    let current = leafId;
397	    while (current !== null && current !== undefined) {
398	      const node = quotas.get(current);
399	      if (node === undefined) {
400	        throw new TypeError(`unknown quota ${String(current)}`);
401	      }
402	      chain.push(node);
403	      current = node.parentId;
404	    }
405	    chain.reverse();
406	    return chain;
407	  }
408	
409	  // Forget a lease from every owner's retired set without touching its
410	  // live usage: the share was already observed expired (a sweep projected
411	  // the retirement before its reclaim event landed).
412	  function purgeRetired(lease) {
413	    const rs = resourceStates.get(lease.resource);
414	    if (rs !== undefined) {
415	      rs.retired.delete(lease.token);
416	    }
417	    for (const quota of lease.chain) {
418	      quota.retired.delete(lease.token);
419	    }
420	  }
421	
422	  // Permanently remove a lease from the table (early release, reclaim, a
423	  // single-occupancy retake, or a replay superseding it). Owners that were
424	  // still counting the share lose it; owners that had already observed it
425	  // expired simply forget its retired entry.
426	  function retirePermanent(lease) {
427	    if (lease === undefined) {
428	      return;
429	    }
430	    const rs = resourceStates.get(lease.resource);
431	    if (rs !== undefined) {
432	      if (!rs.retired.has(lease.token)) {
433	        rs.live -= 1;
434	      }
435	      rs.retired.delete(lease.token);
436	    }
437	    for (const quota of lease.chain) {
438	      if (!quota.retired.has(lease.token)) {
439	        quota.live -= 1;
440	      }
441	      quota.retired.delete(lease.token);
442	    }
443	  }
444	
445	  // Reconcile one occupancy owner (a resource or one quota level) with the
446	  // passed clock reading. Occupancy is judged the way isLive judges it -
447	  // `expiresAt > now` - at every call, so a reading that goes backwards
448	  // revives shares an earlier reading had already retired. The owner's
449	  // watermark makes a monotonic sequence of readings pop lazily in expiry
450	  // order, and a backwards reading walk the retired set back onto the heap.
451	  function reconcile(owner, now) {
452	    const retired = [];
453	    if (now === owner.watermark && owner.version === owner.checkedVersion) {
454	      return retired;
455	    }
456	    if (now > owner.watermark) {
457	      while (owner.heap.size > 0) {
458	        const node = owner.heap.peek();
459	        if (node.expiresAt > now) {
460	          break;
461	        }
462	        owner.heap.pop();
463	        const lease = leases.get(node.token);
464	        if (lease === undefined) {
465	          // Released or reclaimed.
466	          continue;
467	        }
468	        if (lease.heapSeq !== node.heapSeq) {
469	          // Superseded by a renewal: discard the old node without retiring
470	          // anything (its heap entry is stale) and keep scanning.
471	          continue;
472	        }
473	        if (owner.retired.has(node.token)) {
474	          // Either a share that revived after a backwards reading and
475	          // expired again, or a share a replay retake structurally
476	          // superseded: its first retirement already moved this owner's
477	          // usage, so the heap node is simply dropped.
478	          continue;
479	        }
480	        owner.retired.set(node.token, {
481	          heapSeq: node.heapSeq,
482	          expiresAt: node.expiresAt,
483	        });
484	        owner.live -= 1;
485	        retired.push(node);
486	      }
487	    } else {
488	      // The reading moved backwards: every retired share that is live again
489	      // under the earlier reading returns, and its node goes back on the heap
490	      // so a later forward reading retires it in proper expiry order.
491	      for (const [token, record] of owner.retired) {
492	        const lease = leases.get(token);
493	        if (lease === undefined || lease.heapSeq !== record.heapSeq) {
494	          // Released/reclaimed meanwhile, or renewed after a revival: the
495	          // old record describes nothing current.
496	          owner.retired.delete(token);
497	          continue;
498	        }
499	        if (record.expiresAt > now) {
500	          owner.retired.delete(token);
501	          const node = {
502	            token,
503	            expiresAt: record.expiresAt,
504	            heapSeq: record.heapSeq,
505	            order: queueOrder++,
506	          };
507	          owner.heap.push(node);
508	          owner.live += 1;
509	          retired.push({ node, revived: true });
510	        }
511	      }
512	    }
513	    owner.watermark = now;
514	    owner.checkedVersion = owner.version;
515	    return retired;
516	  }
517	
518	  // Project a batch of global reclaim nodes through every owner they
519	  // occupy before wake planning in a sweep. Returns a record able to put
520	  // every owner exactly back if the log write fails.
521	  function projectReclaims(due, now) {
522	    const touched = [];
523	    const seen = new Set();
524	    const touch = (owner) => {
525	      if (owner !== undefined && !seen.has(owner)) {
526	        seen.add(owner);
527	        touched.push({ owner, watermark: owner.watermark, checkedVersion: owner.checkedVersion, retired: [] });
528	      }
529	    };
530	    for (const node of due) {
531	      const lease = leases.get(node.token);
532	      touch(resourceStates.get(lease.resource));
533	      for (const quota of lease.chain) {
534	        touch(quota);
535	      }
536	    }
537	    for (const entry of touched) {
538	      entry.retired = reconcile(entry.owner, now);
539	    }
540	    return touched;
541	  }
542	
543	  function revertProjections(touched) {
544	    for (const entry of touched) {
545	      const { owner } = entry;
546	      for (const item of entry.retired) {
547	        const node = item.node ?? item;
548	        owner.retired.delete(node.token);
549	        if (item.revived) {
550	          owner.live -= 1;
551	        } else {
552	          owner.live += 1;
553	        }
554	        owner.heap.push(node);
555	      }
556	      owner.watermark = entry.watermark;
557	    }
558	  }
559	
560	  function getSlots(resource) {
561	    let set = slots.get(resource);
562	    if (set === undefined) {
563	      set = new Set();
564	      slots.set(resource, set);
565	    }
566	    return set;
567	  }
568	
569	  function addSlot(resource, token) {
570	    getSlots(resource).add(token);
571	  }
572	
573	  function removeSlot(resource, token) {
574	    const set = slots.get(resource);
575	    if (set === undefined) {
576	      return false;
577	    }
578	    const removed = set.delete(token);
579	    if (removed && set.size === 0) {
580	      slots.delete(resource);
581	    }
582	    return removed;
583	  }
584	
585	  // Drop expired-but-unswept credentials from a single-occupancy resource
586	  // that is about to be granted: the resource is free, and a retaken lease
587	  // must never be reported as reclaimed later. Mirrors the retake rule. Share
588	  // resources never displace anyone, so they never call this.
589	  function dropStaleSlots(resource, now) {
590	    const rs = resourceStates.get(resource);
591	    if (rs === undefined) {
592	      return;
593	    }
594	    // Permanent removal consults each owner's retired set itself and
595	    // only decrements owners that were still counting the share, so no
596	    // prior reconcile is needed here.
597	    const set = slots.get(resource);
598	    if (set === undefined) {
599	      return;
600	    }
601	    for (const token of [...set]) {
602	      const lease = leases.get(token);
603	      if (!isLive(lease, now)) {
604	        retirePermanent(lease);
605	        leases.delete(token);
606	        set.delete(token);
607	      }
608	    }
609	    if (set.size === 0) {
610	      slots.delete(resource);
611	    }
612	  }
613	
614	  // Any live holder of a resource. Reconcile first retires every share due
615	  // at the passed reading, so the heap top that still names a current lease
616	  // is a live one; stale nodes (renewed, released, reclaimed) pop away.
617	  // Work is O(expired * log n), never a scan of every share.
618	  function liveHolder(resource, now) {
619	    const rs = resourceStateFor(resource);
620	    reconcile(rs, now);
621	    while (rs.heap.size > 0) {
622	      const node = rs.heap.peek();
623	      const lease = leases.get(node.token);
624	      if (lease === undefined || lease.heapSeq !== node.heapSeq) {
625	        rs.heap.pop();
626	        continue;
627	      }
628	      return lease.holder;
629	    }
630	    return null;
631	  }
