633	  function fsyncDirectory(file) {
634	    // Best-effort durability for the rename itself: on platforms where
635	    // fsyncing a directory handle is unsupported there is nothing to sync,
636	    // and the rename has already committed by the time this runs.
637	    try {
638	      const fd = fs.openSync(path.dirname(file), 'r');
