node --input-type-module -e "
import('./src/index.js').then(({ createRegistry, LeaseFencedError }) => {
  let now = 0;
  const r = createRegistry({ ttlMs: 100, clock: () => now });
  const a = r.acquire('r', 'A');
  console.log('first epoch:', a.epoch, 'epoch(r):', r.epoch('r'));
  console.log('assert ok:', r.assertLease('r', a.token, 1));
  // renew keeps epoch
  now = 10; r.renew(a.token);
  console.log('after renew epoch:', r.epoch('r'), a.epoch);
  // release then retake
  r.release(a.token);
  console.log('after release epoch stays:', r.epoch('r'));
  const b = r.acquire('r', 'B');
  console.log('retake epoch:', b.epoch);
  // same holder retake after expiry
  now = 50;
  const c = r.acquire('r', 'B');
  console.log('same holder retake epoch:', c.epoch, 'stats granted:', r.stats().granted);
  // fence cases
  for (const [label, fn] of [
    ['old token', () => r.assertLease('r', b.token, 2)],
    ['old epoch arg', () => r.assertLease('r', c.token, 2)],
    ['unknown resource', () => r.assertLease('nope', c.token, 3)],
    ['unknown token', () => r.assertLease('r', 'zzz', 3)],
  ]) {
    try { fn(); console.log(label, 'NO THROW'); }
    catch (e) { console.log(label, '->', e.name, e.code); }
  }
  // type errors
  for (const args of [[1, c.token, 3], ['r', 5, 3], ['r', c.token, 1.5], ['r', c.token, NaN], ['r', c.token, Infinity]]) {
    try { r.assertLease(...args); console.log('bad args NO THROW', args); }
    catch (e) { console.log('typeerr', e instanceof TypeError); }
  }
  // expiry fences
  now = 200;
  try { r.assertLease('r', c.token, 3); console.log('expired NO THROW'); }
  catch (e) { console.log('expired ->', e.code); }
  // failed acquire does not consume epoch
  now = 0;
  const x = r.acquire('x', 'h');
  let threw = false;
  try { r.acquire('x', 'k'); } catch (e) { threw = e.code; }
  console.log('contended:', threw, 'epoch(x):', r.epoch('x'));
});
"

