  assert.equal(group.status, 'waiting');
  registry.release(a.token);
  assert.equal(group.status, 'granted');
  assert.deepEqual(group.leases.map((l) => l.epoch), [2, 2]);
  assert.equal(registry.epoch('a'), 2);
