test('several groups woken in one cascade draw strictly increasing epochs', () => {
  const clock = fakeClock(0);
  const registry = createRegistry({ ttlMs: 100, clock });
  registry.acquire('a', 'h', 10);
  registry.acquire('b', 'h', 10);
