  registry.release(freed.token); // freed has no live lease but epoch must stay 1
  const again = registry.acquire('freed', 'h2', 200); // epoch 2
  registry.declareResource('pool', 3);
  registry.acquire('pool', 'p1', 200);
  registry.acquire('pool', 'p2', 200);
  const group = registry.acquireAll(['keep', 'g'], 'G', [200, 200]);
  void keep;
  // keep's group acquisition was blocked above? No: keep is held. Build a
