node --input-type=module -e "
import('./src/index.js').then(async ({ createRegistry, LogFileError }) => {
  const fs = await import('node:fs'); const os = await import('node:os'); const path = await import('node:path');
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ep-rb-'));
  const p = path.join(dir, 'e.log');
  const sabotage = (f) => { fs.renameSync(f, f+'.bak'); fs.mkdirSync(f); };
  const restore = (f) => { fs.rmdirSync(f); fs.renameSync(f+'.bak', f); };
  let now = 0; const clock = () => now;
  const r = createRegistry({ ttlMs: 100, clock, logPath: p });
  const a = r.acquire('r', 'h1');
  const ticket = r.acquire('r', 'b', 40, 1000);
  now = 10;
  sabotage(p);
  try { r.release(a.token); } catch (e) {}
  restore(p);
  console.log('epoch after failed waking release:', r.epoch('r'), '(want 1)');
  r.release(a.token);
  console.log('ticket epoch after successful wake:', ticket.epoch, '(want 2)', 'epoch(r):', r.epoch('r'));
  fs.rmSync(dir, {recursive:true,force:true});
});
"
